CREATE SCHEMA IF NOT EXISTS framework_test;
CREATE TABLE IF NOT EXISTS framework_test.records (id text PRIMARY KEY, tenant_id text NOT NULL, value jsonb NOT NULL, version integer NOT NULL DEFAULT 1);
CREATE INDEX IF NOT EXISTS records_tenant_idx ON framework_test.records (tenant_id, id);
CREATE TABLE IF NOT EXISTS framework_test.idempotency (scope text NOT NULL, key text NOT NULL, fingerprint text NOT NULL, status text NOT NULL, response jsonb, PRIMARY KEY (scope, key));
CREATE TABLE IF NOT EXISTS framework_test.outbox (id text PRIMARY KEY, tenant_id text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS framework_test.audit (id text PRIMARY KEY, tenant_id text NOT NULL, record_id text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS framework_test.cache_generations (scope text PRIMARY KEY, generation bigint NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS framework_test.leases (lease_key text PRIMARY KEY, owner text NOT NULL, fence bigint NOT NULL, expires_at_ms bigint NOT NULL);
CREATE TABLE IF NOT EXISTS framework_test.finalizers (finalizer_key text PRIMARY KEY, owner text NOT NULL, fence bigint NOT NULL, state text NOT NULL);
CREATE TABLE IF NOT EXISTS framework_test.inbox_records (record_key text PRIMARY KEY, record jsonb NOT NULL, revision bigint NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS framework_test.outbox_delivery_records (record_key text PRIMARY KEY, record jsonb NOT NULL, revision bigint NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS framework_test.ev1_business_effects (id text PRIMARY KEY, value text NOT NULL);
CREATE TABLE IF NOT EXISTS framework_test.j1_jobs (id text PRIMARY KEY, worker_id text NOT NULL, claim_token text NOT NULL, attempt integer NOT NULL, lease_expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS framework_test.job_progress (job_id text PRIMARY KEY REFERENCES framework_test.j1_jobs(id) ON DELETE CASCADE, attempt integer NOT NULL, sequence bigint NOT NULL, percent double precision, checkpoint jsonb, updated_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS framework_test.workflows (id text PRIMARY KEY, workflow_type text NOT NULL, workflow_version integer NOT NULL, execution_scope jsonb NOT NULL, status text NOT NULL, current_step text NOT NULL, variables jsonb NOT NULL, step_attempt integer NOT NULL DEFAULT 0, compensation_stack jsonb NOT NULL DEFAULT '[]', waiting_signal text, wake_at timestamptz, outcome text, failure jsonb, revision bigint NOT NULL DEFAULT 0, lease_owner text, claim_token text, lease_expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), updated_at timestamptz NOT NULL DEFAULT clock_timestamp());
ALTER TABLE framework_test.workflows ADD COLUMN IF NOT EXISTS failure jsonb;
CREATE INDEX IF NOT EXISTS workflows_due_idx ON framework_test.workflows (status, wake_at, lease_expires_at, updated_at);
CREATE TABLE IF NOT EXISTS framework_test.workflow_signals (id text PRIMARY KEY, instance_id text NOT NULL REFERENCES framework_test.workflows(id) ON DELETE CASCADE, name text NOT NULL, payload jsonb NOT NULL, delivered_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE IF NOT EXISTS framework_test.temporal_heads (scope_id text NOT NULL, entity_type text NOT NULL, entity_id text NOT NULL, revision bigint NOT NULL CHECK (revision > 0), occurred_at timestamptz NOT NULL, kind text NOT NULL CHECK (kind IN ('created','updated','deleted','restored')), CHECK (revision > 1 OR kind = 'created'), PRIMARY KEY (scope_id, entity_type, entity_id));
CREATE TABLE IF NOT EXISTS framework_test.temporal_revisions (scope_id text NOT NULL, entity_type text NOT NULL, entity_id text NOT NULL, revision bigint NOT NULL CHECK (revision > 0), occurred_at timestamptz NOT NULL, kind text NOT NULL CHECK (kind IN ('created','updated','deleted','restored')), state jsonb, entity_version bigint, event_id text, audit_id text, CHECK ((kind = 'deleted' AND state IS NULL) OR (kind <> 'deleted' AND state IS NOT NULL)), PRIMARY KEY (scope_id, entity_type, entity_id, revision));
CREATE INDEX IF NOT EXISTS temporal_revisions_time_idx ON framework_test.temporal_revisions (scope_id, entity_type, entity_id, occurred_at, revision);
CREATE TABLE IF NOT EXISTS framework_test.temporal_snapshots (scope_id text NOT NULL, entity_type text NOT NULL, entity_id text NOT NULL, revision bigint NOT NULL CHECK (revision >= 0), occurred_at timestamptz NOT NULL, state jsonb, PRIMARY KEY (scope_id, entity_type, entity_id, revision));
CREATE TABLE IF NOT EXISTS framework_test.sequences (scope_id text NOT NULL, name text NOT NULL, period text NOT NULL, value bigint NOT NULL CHECK (value > 0), PRIMARY KEY (scope_id, name, period));
ALTER TABLE framework_test.temporal_heads ADD COLUMN IF NOT EXISTS occurred_at timestamptz NOT NULL DEFAULT '-infinity';
ALTER TABLE framework_test.temporal_heads ADD COLUMN IF NOT EXISTS kind text NOT NULL DEFAULT 'created';
